const today = new Date().toISOString().split('T')[0];
const items = $json.data?.boards?.[0]?.items_page?.items || [];

const filtered = items.filter(item => {
  const priority = item.column_values.find(c => c.id === 'project_prority')?.text || '';
  const timeline = item.column_values.find(c => c.id === 'project_timeline')?.text || '';
  const status = item.column_values.find(c => c.id === 'project_status')?.text || '';
  const isHighPriority = ['high', 'urgent', 'critical'].includes(priority.toLowerCase());
  const notDone = status.toLowerCase() !== 'done';
  let isActive = false;
  if (timeline) {
    const parts = timeline.split(' - ');
    const endDate = parts[1] ? parts[1].trim() : parts[0].trim();
    isActive = endDate >= today;
  }
  return isHighPriority && notDone && isActive;
}).map(item => ({
  name: item.name,
  client: item.group?.title || '',
  priority: item.column_values.find(c => c.id === 'project_prority')?.text || '',
  status: item.column_values.find(c => c.id === 'project_status')?.text || '',
  timeline: item.column_values.find(c => c.id === 'project_timeline')?.text || ''
}));

return [{ json: { intent: 'high_priority_today', data: filtered, message: $('Parse Intent1').first().json.message, contextLines: $('Parse Intent1').first().json.contextLines } }];

